import{_ as s,o as p,c as e,a3 as r}from"./chunks/framework.BwzYn71E.js";const k=JSON.parse('{"title":"建立售后(义诊答疑)部门","description":"","frontmatter":{"translationSource":{"title":"建立售后\\\\(义诊答疑\\\\)部门","archivedAt":"2026-10-29","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AnG8YkyaK2VGhXykemIDer","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/establishing-a-customer-support-department"}]]},"headers":[],"relativePath":"zh/establishing-a-customer-support-department.md","filePath":"zh/page-AnG8YkyaK2VGhXykemIDer.md"}'),n={name:"zh/establishing-a-customer-support-department.md"};function t(l,a,o,i,c,d){return p(),e("div",null,[...a[0]||(a[0]=[r('<div class="logistics-content"><h1 id="建立售后-义诊答疑-部门" tabindex="-1">建立售后(义诊答疑)部门 <a class="header-anchor" href="#建立售后-义诊答疑-部门" aria-label="Permalink to &quot;建立售后\\(义诊答疑\\)部门&quot;">​</a></h1><blockquote><p>源页面 ID：<code>AnG8YkyaK2VGhXykemIDer</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AnG8YkyaK2VGhXykemIDer" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>由于<a href="/endfield-skydoc/zh/issues-with-publishing-results">成果公开流程问题总结</a>，决定建立售后部门</p><p>统计售后相关人员</p><p><span class="mark-grey">#言：售后/答疑应当具有追根溯源解决大部分可能问题的能力，具体来说需要能通过报表基本准确的反推问题而这需要对所有模块的功能有清晰的认识和对自动配平/自适应装置的原理要有基本的认识；当然，需要一定的空余时间处理问题/学习需要的知识</span></p><p><span class="mark-grey">#沃 ：诶，那直播呢🤔直播没写进去吗</span></p><p><span class="mark-grey">#东 ：个人认为直播是问诊的手段和保护方式也就是说如果要上号的话应该直播留痕（</span><span class="mark-grey"><s>？感觉还是想发牢骚，这么多天售后下来确实给到人很充足的乐子（？）和自我认同感，并且大部分的人就算不看文档也能解决问题，但看文档的职责就落到售后头上了（我翻了常见问题null遍），售后看完一个截图糊脸上问题就解决了，真不行上号看看也就完成了。怕的是有些指令不听，有自己想法（不是指小巧思）或者交流无效的（仙家对话），相比之下小巧思似乎没那么可怕（？！）我既然来了我就是想解决问题，多帮人，学习技术的，那我为什么要动不动破防。</s></span><span class="mark-grey">（看到这里的盆U，相信是能理解售后的现状的x-x）</span></p><p><span class="mark-grey">#东：评论区根本就不是一个能答疑的地方</span></p><p><span class="mark-grey">#jnk ：</span><a href="/endfield-skydoc/zh/issues-with-publishing-results">成果公开流程问题总结</a></p><p><span class="mark-grey">#Disadvantage：考虑到目前的问诊存在大量的重复性操作（比如报表的提醒）需要考虑一些方法（通过群问题及群公告使用户了解问诊前提）来规避以提升效率去应对可能的大量问诊需求</span></p><p><span class="mark-grey">#言：这么说的话不知道能不能做一个监控群聊然后初筛是否能吻合常见问题的bot，最好是嫖一下免费ai（</span></p><p><span class="mark-grey">#东：</span><span class="mark-grey"><s>感觉q群管家即可（？</s></span><span class="mark-grey">基于</span><span class="mark-grey"><u>鸿蒙系统</u></span><span class="mark-grey">的限制，我认为Q群管家不可行</span><span class="mark-grey"><s>鸿蒙是区</s></span></p><p>建立相关群聊</p><p><span class="mark-grey">此处不应当放群号，由相关人员手动审核拉入</span></p><p><span id="source-block-DheeoJbZgduO0Z9vZfkSv3"></span></p><h2 id="答疑守则-待编写" tabindex="-1">答疑守则（待编写 <a class="header-anchor" href="#答疑守则-待编写" aria-label="Permalink to &quot;答疑守则（待编写&quot;">​</a></h2><p><span class="mark-grey">#东：首先作为答疑不能首先对用户哈气，也不应该对用户哈气，骂人要文明，其次别的售后哈气要及时按住，答疑不是骂街，最后要尊重每一个用户，即是是个乱改产线不听指令的哈基人，慈悲之下众生平等，我们可以不答，但是答就要负责任，答好了</span></p><p><span class="mark-grey">#言：不想答可以忽略，但是如果要答就要忍受一切后续问题或者转交无法解决的问题时应当明确后续跟进人选，忌发泄情绪忌半途而废。（#东：智齿）</span></p><p><span id="source-block-MCp3KAJDxAeiKPQNN5mI57"></span></p><h2 id="用户守则-待编写" tabindex="-1">用户守则（待编写 <a class="header-anchor" href="#用户守则-待编写" aria-label="Permalink to &quot;用户守则（待编写&quot;">​</a></h2><p><span class="mark-grey">#言 有问题多去群/答疑网站并以答疑人员回答为准（虽然答疑人员不一定绝对正确，但是不可否认的是他们比多数人更加熟悉产线并随时可以转接开发人员），也就是说不要轻易相信其他渠道的回复，也不要在答疑人员处固执己见。</span></p><p><span class="mark-grey"><s>#言 应该多看当期产线的视频和文档（文档是正常来说获取蓝图的地方，注意评论区出现的蓝图码可能不是最新版本）和视频，视频对几乎所有必要的操作都会展示而文档中对很多常见问题已做出了回答，提出能通过以上手段解决的问题是对答疑人员不必要的负担（即使是不能全部看懂但是如果努力过也能大幅减小答疑人员的负担），请不要这样消费我们的热情和善意。</s></span></p><p><span class="mark-grey">#言 原则上我们不容许没有首先查阅视频/文档/游戏百科而发起的简单问题，在这些容易查看的信息源中对相当多常见问题都做了解答。提问这些问题对您来说或许不过是三两句话，但是对答疑人员来说大基数的人流反复提出同样的问题是巨大的精力乃至热情和善意的消耗（并且在我看来这是不太道德的），为了让答疑人员有足够的精力去解决更需要他们的疑难杂症，或忽略容易通过查阅视频/文档/游戏百科解决的问题——当然此时或许会有除答疑外的热心群友的回答，但我们不负责这些回答的正确性。</span></p><p>#JMY 群里严禁发送恐怖，血腥，擦边及黄色内容，第一次禁言1天，第二次直接踢加拉黑</p><p><span class="mark-grey">#Disadvantage：如果执行问诊结束即清理的做法一定程度上就能规避这样的情况，像是这样的群规感觉更适合大群（？#东：有点废人吧这样子，或者有时候也不太好确认问诊是否结束(?那不真成医院了</span><br><span class="mark-grey">#言 没有警告的余裕吗，会不会太严格了。而且其实也不好分辨违反几次，不应该立执行不能的规矩。</span></p><p>#jmy 可以搞一个专门的闲聊群，问诊结束后拉到闲聊群，给问诊群空位置</p><p>#disadvantage：问诊群一定要问诊 <span class="mark-grey">我去不早说#jmy#东：我去不早说#151：我去不早说</span></p><p><span class="mark-grey">#Disadvantage：严禁在不完全理解产线运行原理的情况下私自修改产线，私自修改导致基建运行异常而进行问诊是浪费问诊人员的时间</span><br> #言 或者至少要告知当前作何修改</p><p><span class="mark-grey">#言 基建答疑群内少聊无关内容，包括不限于其他游戏、本家、抽卡、战斗排轴、邪道滑索。视情况予以禁言。</span></p><p><span class="mark-grey">#东：不准攻击售后</span><span class="mark-grey"><s>，售后是下届猪人</s></span><span class="mark-grey"><br> #言 直接群内不允许人身攻击？无论是群友还是老群友还是答疑还是开发还是改区。人身攻击标准由管理自行决定。</span></p><p><span id="source-block-D4gufk7H4xiLthYE7JHT6d"></span></p><h2 id="qq群公告-随时调整" tabindex="-1">qq群公告（随时调整 <a class="header-anchor" href="#qq群公告-随时调整" aria-label="Permalink to &quot;qq群公告（随时调整&quot;">​</a></h2><p><span class="mark-grey">#东：有没有可能从这里开始就没人看了（？#言 那下面说的明明白白，该忽略的忽略该不负责的不负责该踢飞的踢飞啊</span></p><p><span class="mark-red"><strong>由于本公告内容过于冗长，实际执行中力度不能和表述一样严厉，大多数情况下仅作为警告的依据。</strong></span></p><p>向群聊内寻求答疑时，鼓励先观看视频/阅读文档/查阅游戏内百科（据说可以有效提高答疑人员好感度）视频链接包含在文档中故仅给出文档链接：<br><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production">1.5智能最大毛产</a><br> 如果想进一步学习该基建原理，开发人员已将需要阅读的文档的链接贴在该文档中。尤其欢迎学习基建原理所产生的疑问。</p><p>向群聊内寻求答疑时，请一律展示以下物品，可以大幅提高问诊效率：<br> （可在报表中点击星标置顶物品方便展示）源矿 蓝铁矿 赤铜矿 赤铜块 蓝铁粉末 赤铜粉末 致密源石粉末 赫铜块 息壤 重息壤 壤晶 灼铜块 分离芯 赤铜溶液 气态赤铜 气态赫铜 气态灼铜 中容武陵电池（默认排序 升序）（若不遵守容易引起答疑人员的反感甚至忽略）</p><p>群内禁止聊敏感内容，包括但不限于恐怖、血腥、擦边、金钱交易，一经发现直接踢出群聊。群内少聊无关内容，包括但不限于其他游戏、本家、抽卡、战斗排轴、邪道滑索，视情况予以禁言。</p><p>以答疑人员（即群管理，暂时不包括群主）的回答为准（虽然答疑人员不一定绝对正确，但是不可否认的是他们比多数人更加熟悉产线并随时可以转接开发人员），也就是说不要轻易相信其他渠道的回复，也不要在答疑人员处固执己见。</p><p>原则上我们不容许没有首先查阅视频/文档/游戏百科而发起的简单问题，在这些容易查看的信息源中对相当多常见问题都做了解答。提问这些问题对您来说或许不过是三两句话，但是对答疑人员来说大基数的人流反复提出同样的问题是巨大的精力乃至热情和善意的消耗，为了让答疑人员有足够的精力去解决更需要他们的疑难杂症，或忽略容易通过查阅视频/文档/游戏百科解决的问题——当然此时或许会有除答疑外的热心群友的回答，但我们不负责这些回答的正确性。</p><p>不允许人身攻击，无论是新群友老群友答疑人员开发人员，任何人可以通过临时会话向群友和管理检举，一经发现将采取长时间禁言。请诸位传递知识和善意而不是戾气并对自己的言行负责。</p><p>为了尽可能保证答疑群有空位接纳新人新问题，每周不定期清理一周未发言的群友。如果有学习更多基建知识意愿，可以临时会话管理/群主以申请。</p><p>对答疑人员来说，不想答可以忽略，但是一旦选择回答就需要全程做到尊重对方的困境和疑问，对自己的答疑行为充分负责，当遇到无法解决的问题时应当明确后续跟进人选并清晰告知提问者后才能转交问题，忌发泄情绪忌半途而废。如果该过程中双方有存在违规，任何人包括当事人可以向管理/群主检举，忌当面对质。</p><p><span id="source-block-FgIi5lmzQCSeiBKEktSP0f"></span></p><h2 id="答疑qq群清理办法" tabindex="-1">答疑qq群清理办法 <a class="header-anchor" href="#答疑qq群清理办法" aria-label="Permalink to &quot;答疑qq群清理办法&quot;">​</a></h2><p><span class="mark-grey">#言 一周一清，清一周不发言的，想进修的给sky留言去特定群聊，想留着给别人帮忙可以弄个群头衔？如果是有问题还没解决可以重新加</span></p><p><span class="mark-grey">#东 清的标准是？长时间不发言？只保留固定人员？</span></p><p><span class="mark-grey">#disadvantage：答疑结束理论上就能清，深入了解可以留着或者转移到其他它群</span></p><p><span id="source-block-K1QLU97ywaQqerFz7hD7qK"></span></p><h2 id="售后-答疑报名处" tabindex="-1">售后/答疑报名处 <a class="header-anchor" href="#售后-答疑报名处" aria-label="Permalink to &quot;售后/答疑报名处&quot;">​</a></h2><p>jmy</p><p>东弓（东弓与葛冰之）</p><p>NH（D-15191）</p><p>凯尔希思衡托</p><p>SSnighter</p><p>Disadvantages</p><p>泥岩___（沃沃头子）</p><p><span id="source-block-n2NeK8zgbi9dRIjBQcTKpl"></span></p><h2 id="售后-答疑名单" tabindex="-1">售后/答疑名单 <a class="header-anchor" href="#售后-答疑名单" aria-label="Permalink to &quot;售后/答疑名单&quot;">​</a></h2><p><span id="source-block-9fU6RZ0Clraa1KB7ThLxkv"></span></p><h2 id="兜底答疑名单" tabindex="-1">兜底答疑名单 <a class="header-anchor" href="#兜底答疑名单" aria-label="Permalink to &quot;兜底答疑名单&quot;">​</a></h2></div>',1)])])}const m=s(n,[["render",t]]);export{k as __pageData,m as default};
